// frontend/src/features/events/pages/EventDetails.js
import React, { useEffect, useState, useContext } from "react";
import { useParams, useNavigate } from "react-router-dom";
import API from "../../../api";
import { AuthContext } from "../../../context/AuthContext";
import EventFeedback from "../components/EventFeedback";
import "../EventDetails.css";

const EventDetails = () => {
  const { eventId } = useParams();
  const navigate = useNavigate();
  const { user } = useContext(AuthContext);

  const [event, setEvent] = useState(null);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(true);
  const [isRegistered, setIsRegistered] = useState(false);
  const [registering, setRegistering] = useState(false);
  const [deleting, setDeleting] = useState(false);

  // 🔥 Banner helper (ADMIN PANEL banner support)
  const getEventBanner = (event) => {
    if (event?.banner) {
      return event.banner.startsWith("http")
        ? event.banner
        : `${process.env.REACT_APP_API_URL}/${event.banner}`;
    }
    return "/default-event-banner.jpg";
  };

  // Fetch event details
  useEffect(() => {
    if (!eventId) {
      setLoading(false);
      return;
    }

    const fetchEvent = async () => {
      try {
        const res = await API.get(`/events/${eventId}`);
        setEvent(res.data);

        // Check registration
        if (user?.role === "student") {
          const regRes = await API.get("/registrations/mine");
          const isReg = (regRes.data || []).some(
            (r) => r.event?._id === eventId || r.event?.eventId === eventId
          );
          setIsRegistered(isReg);
        }
      } catch (err) {
        setMessage("Event not found");
      } finally {
        setLoading(false);
      }
    };

    fetchEvent();
  }, [eventId, user]);

  // Register
  const handleRegister = async () => {
    setMessage("");

    if (!user) {
      setMessage("Please login to register");
      return;
    }

    if (user.role !== "student") {
      setMessage("Only students can register");
      return;
    }

    try {
      setRegistering(true);
      await API.post(`/registrations`, { eventId });
      setIsRegistered(true);
      setMessage("✓ Registered successfully!");

      const res = await API.get(`/events/${eventId}`);
      setEvent(res.data);
    } catch (err) {
      setMessage("❌ Registration failed");
    } finally {
      setRegistering(false);
    }
  };

  // Unregister
  const handleUnregister = async () => {
    if (!window.confirm("Cancel registration?")) return;

    try {
      setRegistering(true);
      await API.delete(`/registrations/event/${eventId}`);
      setIsRegistered(false);
      setMessage("✓ Unregistered successfully!");

      const res = await API.get(`/events/${eventId}`);
      setEvent(res.data);
    } catch (err) {
      setMessage("❌ Unregistration failed");
    } finally {
      setRegistering(false);
    }
  };

  // Delete (Admin)
  const handleDeleteEvent = async () => {
    if (!window.confirm("Delete this event permanently?")) return;

    try {
      setDeleting(true);
      await API.delete(`/events/${eventId}`);
      setMessage("✓ Event deleted");
      setTimeout(() => navigate("/events"), 1500);
    } catch (err) {
      setMessage("❌ Failed to delete event");
      setDeleting(false);
    }
  };

  if (loading) {
    return <div className="event-details">⏳ Loading event...</div>;
  }

  if (!event) {
    return (
      <div className="event-details">
        <p>Event not found</p>
        <button onClick={() => navigate("/events")}>← Back</button>
      </div>
    );
  }

  const isFull = event.currentRegistrations >= event.maxRegistrations;
  const isPast = new Date(event.date) < new Date();
  const isDisabled = event.status !== "active" || isPast;

  const hallName =
    typeof event.hall === "string" ? event.hall : event.hall?.name;

  return (
    <div className="event-details">
      <button className="back-btn" onClick={() => navigate("/events")}>
        ← Back
      </button>

      {/* 🔥 HERO BANNER */}
      <div className="event-hero">
        <img
          src={getEventBanner(event)}
          alt={event.title}
          className="event-hero-img"
        />
        <div className="hero-overlay">
          <h1>{event.title}</h1>
          {event.category && (
            <span className="hero-category">{event.category}</span>
          )}
        </div>
      </div>

      <div className="details-container">
        <div className="details-grid">
          {/* LEFT */}
          <div className="details-left">
            <section>
              <h3>📖 About Event</h3>
              <p>{event.description}</p>
            </section>

            <section>
              <h3>📅 Schedule</h3>
              <p>
                {new Date(event.date).toLocaleDateString()} |{" "}
                {event.startTime} - {event.endTime}
              </p>
            </section>

            <section>
              <h3>📍 Location</h3>
              <p>{hallName || "TBD"}</p>
            </section>

            <section>
              <h3>👤 Organizer</h3>
              <p>{event.organizerName}</p>
            </section>

            <section>
              <h3>🏢 Department</h3>
              <p>{event.department}</p>
            </section>
          </div>

          {/* RIGHT */}
          <div className="details-right">
            <div className="registration-card">
              <h2>Registration</h2>

              {user?.role === "admin" && (
                <button
                  className="btn-delete-admin"
                  onClick={handleDeleteEvent}
                  disabled={deleting}
                >
                  {deleting ? "Deleting..." : "🗑️ Delete Event"}
                </button>
              )}

              <p>
                👥 {event.currentRegistrations}/{event.maxRegistrations} registered
              </p>

              {isDisabled ? (
                <p>This event is not available</p>
              ) : isFull ? (
                <button disabled>Event Full</button>
              ) : isRegistered ? (
                <button onClick={handleUnregister} disabled={registering}>
                  Cancel Registration
                </button>
              ) : user?.role === "student" ? (
                <button onClick={handleRegister} disabled={registering}>
                  Register Now
                </button>
              ) : (
                <p>Login as student to register</p>
              )}

              {message && <p className="message">{message}</p>}
            </div>

            {/* Feedback */}
            <EventFeedback eventId={eventId} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default EventDetails;
